/**
 * O(1) quote lookup by global index (0..9999) without requiring full array traversal.
 */
export function getHealthQuoteAt(globalIndex: number): string {
  const normalized = ((globalIndex % 10000) + 10000) % 10000;
  const catIndex = normalized % 5;
  const itemIndex = Math.floor(normalized / 5);
  const seed = CATEGORY_SEEDS[catIndex];
  return `${seed.emojis[itemIndex % 10]} ${seed.prefixes[itemIndex >> 4]}${seed.suffixes[itemIndex & 15]}`;
}

